"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[832],{7183:function(e,t,a){a.d(t,{Y:function(){return r},Z:function(){return o}});var n=a(2265),i=a(7616);function s(e){document.title=e.title;let t=document.querySelector('meta[name="description"]');t||((t=document.createElement("meta")).setAttribute("name","description"),document.head.appendChild(t)),t.setAttribute("content",e.description)}function o(e){let{page:t}=e,{t:a}=(0,i.Z)();return(0,n.useEffect)(()=>{let e=a.meta[t];e&&s(e)},[a,t]),null}function r(e){let{title:t,description:a}=e;return(0,n.useEffect)(()=>{s({title:"".concat(t," | WebAtlas"),description:a})},[t,a]),null}},9675:function(e,t,a){a.d(t,{Bl:function(){return r},u3:function(){return s},zQ:function(){return o}});let n=[{slug:"booking-website-morocco-clinics",title:"Why Moroccan Clinics Lose Patients Without an Online Booking System",excerpt:"Patients search at night, compare on mobile, and book whoever makes it easiest. Here is what a functional booking website actually changes for clinics in Casablanca, Rabat, and Marrakech.",date:"2026-05-12",readTime:"6 min",category:"Booking Systems",author:"WebAtlas",tags:["Morocco","clinics","booking engine","Casablanca"],content:["If you run a clinic, dental practice, or aesthetic studio in Morocco, your patients are not calling during business hours anymore. They search at 10 PM, compare three options on their phone, and book with whoever lets them confirm an appointment in under 60 seconds.","A brochure website with a phone number is not a booking system. It is a filter that sends motivated patients to competitors who invested in online scheduling.","## What a real booking engine includes","A functional clinic website built for conversion includes: real-time availability synced to your calendar, service menus with duration and pricing, SMS or WhatsApp confirmations, and an admin view so your receptionist is not copying appointments from paper.","WebAtlas builds these systems in 10–14 days with fixed pricing from $1,200. You see a live preview before you pay anything.","## The numbers we see consistently","Clinics moving from phone-only scheduling to integrated online booking typically see 2–3\xd7 more weekly appointments within the first month, with no-show rates dropping 40–60% when automated reminders are enabled.","## Morocco-specific considerations","French and Arabic language support matters. RTL layout for Arabic is not optional if you serve local and diaspora clients. Payment integration (CMI, Stripe, or cash-on-visit confirmation) should match how your patients actually pay.","## Next step","Send us your current site URL. We will audit what it is costing you and build a free preview of what a booking-first version looks like — no contract required."]},{slug:"riad-direct-booking-marrakech",title:"How Riads in Marrakech Cut OTA Commissions with Direct Booking Websites",excerpt:"Booking.com takes 15–20% per reservation. A direct booking engine on your own domain recovers thousands per month — if the experience matches what guests expect from OTAs.",date:"2026-05-28",readTime:"7 min",category:"Hospitality",author:"WebAtlas",tags:["riad","Marrakech","direct booking","hospitality"],content:["Marrakech riads and boutique hotels live in a paradox: guests discover you on Instagram and Booking.com, but the commission structure means your best months still feel thin.","Direct booking is not about removing OTAs entirely. It is about giving repeat guests, wedding parties, and high-intent searchers a reason to book on your site instead of a platform that takes a cut.","## What guests need to see before they pay",'Room galleries that load fast on mobile. Real-time availability — not a "contact us" form. Secure payment or deposit collection. Confirmation in French, English, and ideally Arabic.',"A PDF rate sheet sent over WhatsApp does not compete with Booking.com. A polished reservation flow does.","## Case pattern: 8-room riad, Marrakech medina","One WebAtlas client shifted from 82% OTA-dependent reservations to 61% direct within three months. Monthly commission savings exceeded $2,800 — more than the entire website project cost.","## Technical requirements that matter","Mobile-first design (most riad bookings start on a phone). Fast load times in Morocco and Europe. Schema markup for local SEO. Multilingual URLs with proper hreflang if you target France and the UK.","## Build timeline and investment","Direct reservation systems typically run $900–$1,800 depending on payment integration and room count. Delivery is 10–14 days with a live preview by day 3."]},{slug:"web-agency-casablanca-vs-freelancer",title:"Web Agency vs Freelancer in Casablanca: What Established Businesses Should Know",excerpt:"The cheapest quote is rarely the lowest total cost. Here is how to evaluate web partners when your site needs to generate revenue — not just exist.",date:"2026-06-03",readTime:"5 min",category:"Agency Guide",author:"WebAtlas",tags:["Casablanca","web agency","Morocco","SMB"],content:['Casablanca has no shortage of people who can put a website online. The question for an established SMB is not "can someone build a site?" — it is "can they build a system that books appointments, captures leads, or processes reservations without breaking in six months?"',"## Freelancer strengths and limits","Freelancers excel at small, well-defined tasks: a landing page, a logo refresh, a WordPress theme tweak. They struggle when scope includes booking logic, multilingual SEO, payment integration, and ongoing handover documentation — unless they are effectively operating as a one-person agency.","## What an agency should deliver","A credible web studio provides: fixed scope and pricing, a preview before payment, source code ownership, performance benchmarks (Core Web Vitals), and a launch checklist — not just a Figma file and a prayer.","## Red flags",'No portfolio of functional builds (only visual mockups). Hourly billing with no cap. "We use WordPress" as the answer to every question. No mention of mobile performance or SEO structure.',"## The WebAtlas model","We are a functional web studio, not a general marketing agency. We build booking engines, lead machines, B2B catalogs, and client portals in 10 days with fixed quotes from $800. You see your site before you commit."]},{slug:"multilingual-website-morocco-export",title:"Multilingual Websites for Moroccan Exporters: French, English, and Arabic Done Right",excerpt:"A French-only site blocks half your buyers. Here is how proper multilingual structure, hreflang, and RTL support turn a catalog into an international sales channel.",date:"2026-06-10",readTime:"6 min",category:"Multilingual",author:"WebAtlas",tags:["export","multilingual","Arabic RTL","B2B"],content:["Moroccan manufacturers and exporters often have strong products and weak web presence. The gap is not design taste — it is language architecture.","International buyers in France, West Africa, and the Gulf expect to browse in their language. Google expects hreflang tags, not Google Translate widgets buried in a footer.","## Three languages, three audiences","French for Francophone Europe and West Africa. English for UK, Gulf, and Southeast Asian buyers. Arabic for regional trust and RTL layout that does not break your grid.","## Beyond translation","Multilingual done right means separate content strategy per market — not word-for-word translation. Product specs, certifications, and RFQ flows should reflect what each buyer segment cares about.","## SEO structure","Clean URL patterns, language switcher with persistent selection, separate meta titles per language, and structured data that references the correct locale.","WebAtlas multilingual trust sites start at $1,000 and include full FR/EN/AR builds with RTL, hreflang, and language-specific conversion paths."]},{slug:"website-cost-morocco-2026",title:"How Much Does a Business Website Cost in Morocco in 2026?",excerpt:"Transparent ranges for lead-capture sites, booking engines, and client portals — and what you should expect at each price point.",date:"2026-06-18",readTime:"5 min",category:"Pricing",author:"WebAtlas",tags:["pricing","Morocco","web design cost","SMB"],content:["Website pricing in Morocco ranges from 3,000 MAD template installs to $5,000+ custom builds. The right budget depends on what the site needs to do — not how many pages it has.","## Lead capture site: $800–$1,400","Multi-step qualification forms, service pages, mobile optimization, basic SEO. Ideal for contractors, real estate, and professional services that need inbound leads.","## Booking engine: $1,200–$2,200","Calendar logic, confirmations, admin dashboard, payment-ready. Clinics, salons, consultants, and law firms.","## Client portal / B2B catalog: $1,500–$2,800","Authentication, file upload, RFQ workflows, multilingual catalogs. Accounting firms, exporters, and B2B suppliers.","## What affects price","Number of integrations, language count, custom business logic, and content volume. WebAtlas quotes fixed prices after a free preview — no hourly surprises.","## Hidden costs to avoid","Monthly page-builder fees, plugin licenses, developer lock-in, and agencies that charge for every text change. You should own your code and hosting."]}],i={en:n,fr:[{slug:"booking-website-morocco-clinics",title:"Pourquoi les cliniques marocaines perdent des patients sans r\xe9servation en ligne",excerpt:"Les patients cherchent le soir, comparent sur mobile et r\xe9servent chez celui qui simplifie le plus. Voici ce qu'un vrai site de r\xe9servation change pour les cliniques \xe0 Casablanca, Rabat et Marrakech.",date:"2026-05-12",readTime:"6 min",category:"Syst\xe8mes de r\xe9servation",author:"WebAtlas",tags:["Maroc","cliniques","moteur de r\xe9servation","Casablanca"],content:["Si vous dirigez une clinique, un cabinet dentaire ou un institut esth\xe9tique au Maroc, vos patients n'appellent plus aux heures de bureau. Ils cherchent \xe0 22 h, comparent trois options sur leur t\xe9l\xe9phone et r\xe9servent chez celui qui leur permet de confirmer un rendez-vous en moins de 60 secondes.","Un site vitrine avec un num\xe9ro de t\xe9l\xe9phone n'est pas un syst\xe8me de r\xe9servation. C'est un filtre qui envoie les patients motiv\xe9s vers des concurrents qui ont investi dans la prise de rendez-vous en ligne.","## Ce qu'un vrai moteur de r\xe9servation inclut","Un site clinique fonctionnel inclut : disponibilit\xe9s en temps r\xe9el synchronis\xe9es avec votre agenda, menus de services avec dur\xe9e et tarifs, confirmations SMS ou WhatsApp, et une vue admin pour que votre accueil ne recopie plus les rendez-vous sur papier.","WebAtlas construit ces syst\xe8mes en 10 \xe0 14 jours avec un prix fixe \xe0 partir de 1 200 $. Vous voyez un aper\xe7u en direct avant tout paiement.","## Les chiffres que nous observons r\xe9guli\xe8rement","Les cliniques passant du t\xe9l\xe9phone seul \xe0 la r\xe9servation en ligne int\xe9gr\xe9e voient g\xe9n\xe9ralement 2 \xe0 3\xd7 plus de rendez-vous hebdomadaires d\xe8s le premier mois, avec une baisse des absences de 40 \xe0 60 % gr\xe2ce aux rappels automatiques.","## Sp\xe9cificit\xe9s marocaines","Le support fran\xe7ais et arabe compte. La mise en page RTL pour l'arabe n'est pas optionnelle si vous servez clients locaux et diaspora. L'int\xe9gration paiement (CMI, Stripe ou confirmation sur place) doit correspondre \xe0 la fa\xe7on dont vos patients paient r\xe9ellement.","## Prochaine \xe9tape","Envoyez-nous l'URL de votre site actuel. Nous auditerons ce qu'il vous co\xfbte et cr\xe9erons un aper\xe7u gratuit de la version orient\xe9e r\xe9servation — sans engagement."]},{slug:"riad-direct-booking-marrakech",title:"Comment les riads de Marrakech r\xe9duisent les commissions OTA gr\xe2ce \xe0 la r\xe9servation directe",excerpt:"Booking.com prend 15 \xe0 20 % par r\xe9servation. Un moteur de r\xe9servation direct sur votre domaine r\xe9cup\xe8re des milliers par mois — si l'exp\xe9rience \xe9gale celle des OTA.",date:"2026-05-28",readTime:"7 min",category:"H\xf4tellerie",author:"WebAtlas",tags:["riad","Marrakech","r\xe9servation directe","h\xf4tellerie"],content:["Les riads et boutique-h\xf4tels de Marrakech vivent un paradoxe : les clients vous d\xe9couvrent sur Instagram et Booking.com, mais les commissions font que vos meilleurs mois restent maigres.","La r\xe9servation directe ne consiste pas \xe0 supprimer les OTA. Il s'agit de donner aux clients fid\xe8les, aux groupes mariage et aux visiteurs \xe0 forte intention une raison de r\xe9server sur votre site plut\xf4t que sur une plateforme qui prend sa part.","## Ce que les clients doivent voir avant de payer","Galeries de chambres rapides sur mobile. Disponibilit\xe9 en temps r\xe9el — pas un formulaire \xab contactez-nous \xbb. Paiement ou acompte s\xe9curis\xe9. Confirmation en fran\xe7ais, anglais et id\xe9alement arabe.","Une grille tarifaire PDF envoy\xe9e sur WhatsApp ne rivalise pas avec Booking.com. Un parcours de r\xe9servation soign\xe9, si.","## Cas type : riad 8 chambres, m\xe9dina de Marrakech","Un client WebAtlas est pass\xe9 de 82 % de r\xe9servations via OTA \xe0 61 % en direct en trois mois. Les \xe9conomies de commission mensuelles ont d\xe9pass\xe9 2 800 $ — plus que le co\xfbt total du site.","## Exigences techniques qui comptent","Design mobile-first (la plupart des r\xe9servations riad commencent sur t\xe9l\xe9phone). Temps de chargement rapides au Maroc et en Europe. Balisage schema pour le SEO local. URLs multilingues avec hreflang si vous ciblez la France et le Royaume-Uni.","## D\xe9lai et investissement","Les syst\xe8mes de r\xe9servation directe co\xfbtent g\xe9n\xe9ralement 900 \xe0 1 800 $ selon paiement et nombre de chambres. Livraison en 10 \xe0 14 jours avec aper\xe7u live au jour 3."]},{slug:"web-agency-casablanca-vs-freelancer",title:"Agence web vs freelance \xe0 Casablanca : ce que les entreprises \xe9tablies doivent savoir",excerpt:"Le devis le moins cher est rarement le co\xfbt total le plus bas. Voici comment \xe9valuer un partenaire web quand votre site doit g\xe9n\xe9rer du chiffre — pas seulement exister.",date:"2026-06-03",readTime:"5 min",category:"Guide agence",author:"WebAtlas",tags:["Casablanca","agence web","Maroc","PME"],content:["\xc0 Casablanca, beaucoup de monde peut mettre un site en ligne. La vraie question pour une PME \xe9tablie n'est pas \xab peut-on faire un site ? \xbb — c'est \xab peut-on construire un syst\xe8me qui prend des rendez-vous, capture des leads ou traite des r\xe9servations sans casser en six mois ? \xbb","## Forces et limites du freelance","Les freelances excellent sur des t\xe2ches petites et bien d\xe9finies : landing page, refonte logo, th\xe8me WordPress. Ils peinent quand le p\xe9rim\xe8tre inclut logique de r\xe9servation, SEO multilingue, paiement et documentation de passation — sauf s'ils op\xe8rent comme une agence une personne.","## Ce qu'une agence doit livrer","Un studio cr\xe9dible fournit : p\xe9rim\xe8tre et prix fixes, aper\xe7u avant paiement, propri\xe9t\xe9 du code source, benchmarks performance (Core Web Vitals) et checklist de lancement — pas seulement un fichier Figma.","## Signaux d'alerte","Pas de portfolio de builds fonctionnels (seulement des maquettes). Facturation horaire sans plafond. \xab On utilise WordPress \xbb comme r\xe9ponse \xe0 tout. Aucune mention de performance mobile ou structure SEO.","## Le mod\xe8le WebAtlas","Nous sommes un studio web fonctionnel, pas une agence marketing g\xe9n\xe9raliste. Nous construisons moteurs de r\xe9servation, machines \xe0 leads, catalogues B2B et portails clients en 10 jours avec devis fixes \xe0 partir de 800 $. Vous voyez votre site avant de vous engager."]},{slug:"multilingual-website-morocco-export",title:"Sites multilingues pour exportateurs marocains : fran\xe7ais, anglais et arabe bien faits",excerpt:"Un site uniquement en fran\xe7ais bloque la moiti\xe9 de vos acheteurs. Voici comment structure multilingue, hreflang et RTL transforment un catalogue en canal de vente international.",date:"2026-06-10",readTime:"6 min",category:"Multilingue",author:"WebAtlas",tags:["export","multilingue","arabe RTL","B2B"],content:["Les industriels et exportateurs marocains ont souvent d'excellents produits et une faible pr\xe9sence web. L'\xe9cart n'est pas le go\xfbt du design — c'est l'architecture linguistique.","Les acheteurs internationaux en France, Afrique de l'Ouest et Golfe veulent naviguer dans leur langue. Google attend des balises hreflang, pas un widget Google Translate en pied de page.","## Trois langues, trois audiences","Fran\xe7ais pour l'Europe francophone et l'Afrique de l'Ouest. Anglais pour Royaume-Uni, Golfe et Asie du Sud-Est. Arabe pour la confiance r\xe9gionale et une mise en page RTL qui ne casse pas votre grille.","## Au-del\xe0 de la traduction","Le multilingue bien fait, c'est une strat\xe9gie de contenu par march\xe9 — pas une traduction mot \xe0 mot. Fiches produits, certifications et parcours RFQ doivent refl\xe9ter ce qui compte pour chaque segment d'acheteurs.","## Structure SEO","URLs propres, s\xe9lecteur de langue persistant, meta titres par langue, et donn\xe9es structur\xe9es avec la bonne locale.","Les sites multilingues WebAtlas d\xe9marrent \xe0 1 000 $ et incluent FR/EN/AR complet avec RTL, hreflang et parcours de conversion par langue."]},{slug:"website-cost-morocco-2026",title:"Combien co\xfbte un site business au Maroc en 2026 ?",excerpt:"Fourchettes transparentes pour sites leads, moteurs de r\xe9servation et portails clients — et ce qu'il faut attendre \xe0 chaque niveau de prix.",date:"2026-06-18",readTime:"5 min",category:"Tarifs",author:"WebAtlas",tags:["tarifs","Maroc","co\xfbt site web","PME"],content:["Les prix de sites au Maroc vont de 3 000 MAD pour un template \xe0 plus de 5 000 $ pour du sur-mesure. Le bon budget d\xe9pend de ce que le site doit faire — pas du nombre de pages.","## Site capture de leads : 800–1 400 $","Formulaires multi-\xe9tapes, pages services, optimisation mobile, SEO de base. Id\xe9al pour artisans, immobilier et services professionnels.","## Moteur de r\xe9servation : 1 200–2 200 $","Logique calendrier, confirmations, tableau de bord admin, pr\xeat pour paiement. Cliniques, salons, consultants, cabinets.","## Portail client / catalogue B2B : 1 500–2 800 $","Authentification, upload fichiers, workflows RFQ, catalogues multilingues. Cabinets comptables, exportateurs, fournisseurs B2B.","## Ce qui influence le prix","Nombre d'int\xe9grations, langues, logique m\xe9tier sur mesure et volume de contenu. WebAtlas quote des prix fixes apr\xe8s aper\xe7u gratuit — pas de surprises horaires.","## Co\xfbts cach\xe9s \xe0 \xe9viter","Abonnements page builder, licences plugins, d\xe9pendance au d\xe9veloppeur, agences qui facturent chaque modification de texte. Vous devez poss\xe9der votre code et h\xe9bergement."]}],ar:[{slug:"booking-website-morocco-clinics",title:"لماذا تخسر العيادات المغربية مرضى بسبب غياب الحجز الإلكتروني",excerpt:"يبحث المرضى ليلاً، يقارنون على الجوال، ويحجزون عند من يُسهّل عليهم ذلك. إليك ما يغيّره موقع حجز فعّال للعيادات في الدار البيضاء والرباط ومراكش.",date:"2026-05-12",readTime:"6 دقائق",category:"أنظمة الحجز",author:"WebAtlas",tags:["المغرب","عيادات","محرك حجز","الدار البيضاء"],content:["إذا كنت تدير عيادة أو عيادة أسنان أو مركز تجميل في المغرب، فمرضاك لم يعودوا يتصلون في أوقات العمل. يبحثون الساعة 10 مساءً، يقارنون ثلاث خيارات على الهاتف، ويحجزون عند من يتيح لهم تأكيد الموعد في أقل من 60 ثانية.","موقع تعريفي برقم هاتف ليس نظام حجز. إنه فلتر يُرسِل المرضى المتحمسين إلى منافسين استثمروا في الجدولة الإلكترونية.","## ما يتضمنه محرك حجز حقيقي","موقع عيادة فعّال يشمل: توفراً فورياً متزامناً مع التقويم، قوائم خدمات بالمدة والسعر، تأكيدات SMS أو واتساب، ولوحة إدارة حتى لا ينسخ الاستقبال المواعيد يدوياً.","WebAtlas تبني هذه الأنظمة في 10–14 يوماً بسعر ثابت من 1,200$. ترى معاينة حية قبل أي دفع.","## الأرقام التي نراها باستمرار","العيادات التي تنتقل من الهاتف فقط إلى الحجز الإلكتروني ترى عادة 2–3\xd7 مواعيد أسبوعية في الشهر الأول، مع انخفاض الغياب 40–60% عند تفعيل التذكيرات التلقائية.","## اعتبارات خاصة بالمغرب","دعم الفرنسية والعربية مهم. تخطيط RTL للعربية ليس اختيارياً إن كنت تخدم محلياً والجالية. تكامل الدفع (CMI أو Stripe أو تأكيد نقدي عند الزيارة) يجب أن يطابق طريقة دفع مرضاك.","## الخطوة التالية","أرسل رابط موقعك الحالي. سنراجع ما يكلفك ونبني معاينة مجانية لنسخة تركز على الحجز — بلا عقد."]},{slug:"riad-direct-booking-marrakech",title:"كيف تقلّص الرياض في مراكش عمولات المنصات بحجز مباشر على موقعها",excerpt:"Booking.com يأخذ 15–20% لكل حجز. محرك حجز مباشر على نطاقك يسترد آلافاً شهرياً — إن كانت التجربة تنافس المنصات.",date:"2026-05-28",readTime:"7 دقائق",category:"الضيافة",author:"WebAtlas",tags:["رياض","مراكش","حجز مباشر","ضيافة"],content:["رياض وبوتيك فنادق مراكش في مفارقة: الضيوف يكتشفونك على إنستغرام وBooking.com، لكن العمولات تجعل أفضل أشهرك رقيقة.","الحجز المباشر ليس إلغاء المنصات كلياً. بل إعطاء الضيوف المتكررين ومجموعات الأعراس والباحثين الجادين سبباً للحجز على موقعك بدل منصة تأخذ نسبتها.","## ما يحتاج الضيوف رؤيته قبل الدفع","معارض غرف سريعة على الجوال. توفر فوري — لا نموذج \xabاتصل بنا\xbb. دفع أو عربون آمن. تأكيد بالفرنسية والإنجليزية والعربية إن أمكن.","جدول أسعار PDF على واتساب لا ينافس Booking.com. مسار حجز مصقول نعم.","## نموذج: رياد 8 غرف، مدينة مراكش","عميل WebAtlas انتقل من 82% حجوزات عبر منصات إلى 61% مباشرة في ثلاثة أشهر. وفّر أكثر من 2,800$ عمولات شهرياً — أكثر من تكلفة الموقع كاملة.","## متطلبات تقنية مهمة","تصميم جوال أولاً. سرعة تحميل في المغرب وأوروبا. Schema للSEO المحلي. روابط متعددة اللغات مع hreflang إن استهدفت فرنسا والمملكة المتحدة.","## الجدول والاستثمار","أنظمة الحجز المباشر عادة 900–1,800$ حسب الدفع وعدد الغرف. التسليم 10–14 يوماً مع معاينة حية بحلول اليوم 3."]},{slug:"web-agency-casablanca-vs-freelancer",title:"وكالة ويب مقابل مستقل في الدار البيضاء: ما يجب أن تعرفه الشركات الراسخة",excerpt:"أرخص عرض نادراً ما يكون أقل تكلفة إجمالية. إليك كيف تقيّم شريك ويب عندما يجب أن يُدرّ موقعك إيرادات — لا أن يوجد فقط.",date:"2026-06-03",readTime:"5 دقائق",category:"دليل الوكالات",author:"WebAtlas",tags:["الدار البيضاء","وكالة ويب","المغرب","شركات صغيرة"],content:["في الدار البيضاء كثيرون يستطيعون وضع موقع أونلاين. السؤال للشركة الصغيرة الراسخة ليس \xabهل يمكن بناء موقع؟\xbb — بل \xabهل يمكن بناء نظام يحجز مواعيد ويجذب عملاء ويعالج حجوزات دون أن ينكسر خلال ستة أشهر؟\xbb","## نقاط قوة وحدود المستقل","المستقلون يتفوقون في مهام صغيرة محددة: صفحة هبوط، شعار، تعديل قالب ووردبريس. يعانون عندما يشمل النطاق منطق حجز وSEO متعدد اللغات ودفع وتوثيق تسليم — إلا إن عملوا كوكالة فرد.","## ما يجب أن تقدمه الوكالة","استوديو موثوق يقدم: نطاقاً وسعراً ثابتين، معاينة قبل الدفع، ملكية الكود، معايير أداء (Core Web Vitals)، وقائمة إطلاق — لا ملف Figma فقط.","## إشارات تحذير","لا محفظة مشاريع وظيفية (فقط تصاميم). فوترة بالساعة بلا سقف. \xabنستخدم ووردبريس\xbb كإجابة لكل سؤال. لا ذكر لأداء الجوال أو بنية SEO.","## نموذج WebAtlas","نحن استوديو ويب وظيفي، ليس وكالة تسويق عامة. نبني محركات حجز وجذب عملاء وكتالوجات B2B وبوابات عملاء في 10 أيام بعروض ثابتة من 800$. ترى موقعك قبل الالتزام."]},{slug:"multilingual-website-morocco-export",title:"مواقع متعددة اللغات للمصدرين المغاربة: فرنسية وإنجليزية وعربية بالشكل الصحيح",excerpt:"موقع فرنسي فقط يحرمك من نصف المشترين. إليك كيف البنية متعددة اللغات وhreflang وRTL تحوّل الكتالوج إلى قناة مبيعات دولية.",date:"2026-06-10",readTime:"6 دقائق",category:"متعدد اللغات",author:"WebAtlas",tags:["تصدير","متعدد اللغات","عربية RTL","B2B"],content:["المصنعون والمصدرون المغاربة غالباً منتجات قوية وحضور ويب ضعيف. الفجوة ليست الذوق — بل الهندسة اللغوية.","المشترون الدوليون في فرنسا وغرب أفريقيا والخليج يتوقعون التصفح بلغتهم. جوجل يتوقع hreflang، لا أداة ترجمة في التذييل.","## ثلاث لغات، ثلاث جماهير","الفرنسية لأوروبا الفرانكفونية وغرب أفريقيا. الإنجليزية للمملكة المتحدة والخليج وجنوب شرق آسيا. العربية للثقة الإقليمية وتخطيط RTL لا يكسر الشبكة.","## أبعد من الترجمة","متعدد اللغات الصحيح يعني استراتيجية محتوى لكل سوق — لا ترجمة حرفية. المواصفات والشهادات ومسارات RFQ تعكس ما يهم كل شريحة مشترين.","## بنية SEO","روابط نظيفة، مبدّل لغة دائم، عناوين meta لكل لغة، وبيانات منظمة باللغة الصحيحة.","مواقع WebAtlas متعددة اللغات تبدأ من 1,000$ وتشمل FR/EN/AR كاملاً مع RTL وhreflang ومسارات تحويل لكل لغة."]},{slug:"website-cost-morocco-2026",title:"كم يكلف موقع أعمال في المغرب عام 2026؟",excerpt:"نطاقات شفافة لمواقع جذب العملاء ومحركات الحجز وبوابات العملاء — وما يجب توقعه عند كل مستوى سعر.",date:"2026-06-18",readTime:"5 دقائق",category:"التسعير",author:"WebAtlas",tags:["تسعير","المغرب","تكلفة موقع","شركات صغيرة"],content:["أسعار المواقع في المغرب من 3,000 درهم لقوالب إلى أكثر من 5,000$ للمخصص. الميزانية المناسبة تعتمد على ما يجب أن يفعله الموقع — لا عدد الصفحات.","## موقع جذب عملاء: 800–1,400$","نماذج متعددة الخطوات، صفحات خدمات، تحسين جوال، SEO أساسي. مثالي للمقاولين والعقار والخدمات المهنية.","## محرك حجز: 1,200–2,200$","منطق تقويم، تأكيدات، لوحة إدارة، جاهز للدفع. عيادات وصالونات ومستشارون ومكاتب محاماة.","## بوابة عميل / كتالوج B2B: 1,500–2,800$","مصادقة، رفع ملفات، مسارات RFQ، كتالوجات متعددة اللغات. محاسبة ومصدرون وموردون B2B.","## ما يؤثر على السعر","عدد التكاملات واللغات والمنطق المخصص وحجم المحتوى. WebAtlas تسعّر ثابتاً بعد معاينة مجانية — بلا مفاجآت بالساعة.","## تكاليف خفية تجنّبها","اشتراكات page builder وتراخيص إضافات واعتماد على المطور ووكالات تفرض على كل تعديل نص. يجب أن تملك الكود والاستضافة."]}]};function s(){var e;let t=arguments.length>0&&void 0!==arguments[0]?arguments[0]:"en";return null!==(e=i[t])&&void 0!==e?e:n}function o(e){let t=arguments.length>1&&void 0!==arguments[1]?arguments[1]:"en";return s(t).find(t=>t.slug===e)}function r(e,t){return new Date(e).toLocaleDateString("ar"===t?"ar-MA":"fr"===t?"fr-FR":"en-GB",{day:"numeric",month:"long",year:"numeric"})}}}]);